import * as THREE from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, float, fract, noise } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * Pricing card 1 label — static engineered-gradient surface with subtle grain
 * and MSDF headline "Pricing 1".
 */
export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const intent = config.intent?.visualSpec ?? {};
  const colors = intent.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  const group = new Group();
  group.name = 'hub-pricing-card-1-label';

  // --- Backdrop plane carrying the engineered gradient + grain ---
  const planeGeo = new PlaneGeometry(1.6, 0.96, 1, 1);
  const planeMat = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1.0,
    side: THREE.DoubleSide,
  });

  const vUv = uv();
  // vertical engineered gradient: ink -> surface -> ink banding
  const topStop = smoothstep(float(0.0), float(0.55), vUv.y);
  const grad = mix(vec3(ink).rgb, vec3(surface).rgb, topStop);
  // subtle grain via hashed noise
  const grainSeed = fract(vUv.x.mul(420.0).add(vUv.y.mul(840.0)).add(time.mul(0.05)));
  const grain = noise(vec3(vUv.mul(180.0), float(0.0)).mul(-0.5).add(0.5)).mul(0.03);
  const colorOut = grad.add(vec3(grain, grain, grain));
  // thin accent hairline at bottom edge
  const accentBand = smoothstep(float(0.0), float(0.018), vUv.y.sub(float(0.04))).oneMinus();
  planeMat.colorNode = mix(colorOut, vec3(accent).rgb, accentBand);

  const plane = new Mesh(planeGeo, planeMat);
  plane.name = 'pricing-card-1-surface';
  plane.position.set(0, 0, 0);
  group.add(plane);

  // --- MSDF headline "Pricing 1" ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labels = [];
  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 39;
    const textObj = ctx.fontAtlas.createText(String(item.text), {
      fontSize,
      color: paper,
      align: 'left',
      letterSpacingPx: 0.5,
    });
    if (textObj) {
      textObj.position.set(-0.62, -0.06, 0.02);
      labels.push(textObj);
      group.add(textObj);
    }
  }

  // --- Attempt texture load for decorative orb (added as subtle overlay) ---
  const texUrl = config.imageUrl;
  let baseTex = null;
  if (texUrl) {
    ctx.textureLoader.loadTexture(texUrl).then((tex) => {
      baseTex = tex;
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // --- GSAP entrance: rise-in settle ---
  const tl = gsap.timeline();
  group.position.set(0.0, 0.0, 0.0);
  group.userData.__localPos = { x: 0, y: 0, z: 0 };
  tl.from(group.position, {
    y: 0.4,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.from(group.scale, {
    x: 0.96,
    y: 0.96,
    duration: 0.7,
    ease: 'power2.out',
  }, '<');

  // settle overshoot
  tl.to(group.scale, {
    x: 1.0,
    y: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  }, '+=0.1');

  const createdBy = tl;

  // --- Event handlers (none wired for static label) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    if (createdBy) createdBy.kill();
    planeGeo.dispose();
    planeMat.dispose();
    if (baseTex) baseTex.dispose && baseTex.dispose();
    labels.forEach((l) => {
      if (l.geometry) l.geometry.dispose();
      if (l.material) {
        if (Array.isArray(l.material)) l.material.forEach((m) => m.dispose());
        else l.material.dispose();
      }
    });
  };

  return group;
}
